        return 1

    queue = deque([(begin, 1)])
    visited = set([begin])

    while queue:
        word, length = queue.popleft()

        if word == end:
            return length

        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c == word[i]:
                    continue
                new_word = word[:i] + c + word[i+1:]
                if new_word in word_set and new_word not in visited:
                    visited.add(new_word)
                    queue.append((new_word, length + 1))

    return 0

def evaluate(expr: str) -> float:
    tokens = tokenize(expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        pos[0] += 1
        return tok

    def parse_expression():
        # handles + and -
        left = parse_term()
        while True:
            tok = peek()
            if tok in ('+', '-'):
                consume()
                right = parse_term()
                if tok == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # handles * and /
        left = parse_factor()
        while True:
            tok = peek()
            if tok in ('*', '/'):
                consume()
                right = parse_factor()
                if tok == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # handles unary minus/plus and primary
        tok = peek()
        if tok == '-':
            consume()
            return -parse_factor()
        elif tok == '+':
            consume()
            return parse_factor()
        else:
            return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == '(':
            consume()
            val = parse_expression()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return val
        elif tok.startswith('-') or tok.startswith('+') or tok.isdigit() or tok == '.':
            # This shouldn't happen because unary is handled in parse_factor
            # But if we see a number token directly
            consume()
            try:
                return float(tok)
            except ValueError:
                raise ValueError(f"Invalid number: {tok}")
        else:
            raise ValueError(f"Unexpected token: {tok}")

    if not tokens:
        raise ValueError("Empty expression")

    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos[0]]}")
    return result


def tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            seen_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not seen_dot)):
                if expr[j] == '.':
                    seen_dot = True
                j += 1
            # Check for scientific notation
            if j < n and expr[j] in 'eE':
                k = j + 1
                if k < n and expr[k] in '+-':
                    k += 1
                if k < n and expr[k].isdigit():
                    while k < n and expr[k].isdigit():
                        k += 1
                    j = k
            token_str = expr[i:j]
            if token_str == '.':
                raise ValueError("Invalid number: '.'")
            try:
                float(token_str)
            except ValueError:
                raise ValueError(f"Invalid number: {token_str}")
            tokens.append(token_str)
            i = j
        else:
            raise ValueError(f"Unexpected character: {c}")
    return tokens

