    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ValueError(f"Invalid number at position {i}")
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            if num_str == '.':
                raise ValueError(f"Invalid number at position {i}")
            try:
                tokens.append(float(num_str))
            except ValueError:
                raise ValueError(f"Invalid number at position {i}")
            i = j
        else:
            raise ValueError(f"Unexpected character: {c}")
    return tokens

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    m, n = len(a), len(b)

    # Build LCS table
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Backtrack to produce diff
    result = []
    i, j = 0, 0
    while i < m and j < n:
        if a[i] == b[j]:
            result.append((' ', a[i]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            result.append(('-', a[i]))
            i += 1
        else:
            result.append(('+', b[j]))
            j += 1

    while i < m:
        result.append(('-', a[i]))
        i += 1
    while j < n:
        result.append(('+', b[j]))
        j += 1

    # Reorder: deletions before insertions for each position
    # Group consecutive operations and reorder - before +
    final = []
    k = 0
    while k < len(result):
        # Collect a block of consecutive non-common operations
        if result[k][0] == ' ':
            final.append(result[k])
            k += 1
        else:
            block = []
            while k < len(result) and result[k][0] != ' ':
                block.append(result[k])
                k += 1
            # Sort: deletions first, then insertions
            deletions = [x for x in block if x[0] == '-']
            insertions = [x for x in block if x[0] == '+']
            final.extend(deletions)
            final.extend(insertions)

    return final

